10	    static int binarySearch(int[] values, int target) {
11	        int left = 0;
12	        int right = values.length - 1;
13	
14	        while (left <= right) {
15	            int middle = midpoint(left, right);
16	            int comparison = Integer.compare(values[middle], target);
17	
18	            if (isMatch(comparison)) {
19	                return middle;
20	            }
21	
22	            if (shouldSearchRight(comparison)) {
23	                left = middle + 1;
24	            } else {
25	                right = middle - 1;
26	            }
27	        }
28	
29	        return NOT_FOUND;
30	    }
